def find_eq(line):
    in_s = False
    s_char = None
    esc = False
    for i,ch in enumerate(line):
        if in_s:
            if esc:
                esc=False
            elif ch=='\\':
                esc=True
            elif ch==s_char:
                in_s=False
        else:
            if ch=='"' or ch=="'":
                in_s=True
                s_char=ch
            elif ch=='=':
                return i
            elif ch=='#':
                break
    return None

def parse_toml_key(s, lineno, raw):
    s=s.strip()
    if s.startswith('"') and s.endswith('"') and len(s)>=2:
        # basic unescape
        inner=s[1:-1]
        return inner.replace('\\"','"').replace('\\\\','\\')
    if s.startswith("'") and s.endswith("'") and len(s)>=2:
        return s[1:-1]
    # bare key: allow A-Za-z0-9_-
