        # We'll split and handle later? For now, treat as error?
        # Actually TOML allows dotted keys. We'll support by returning dotted? Caller must handle.
        # Let's split on . not in quotes (simplify: split)
        return s  # caller will handle?
    raise TomlError(lineno, raw, f"invalid key `{s}`")

def parse_toml_value(s, lineno, raw):
    s=s.strip()
    if not s:
        raise TomlError(lineno, raw, "expected value")
    # strip trailing comment not in string?
    s = strip_comment(s)
    s=s.strip()
    if s.startswith('"'):
        # basic string, find closing "
