    if s=='false':
        return False
    # integer? float? try int
    try:
        if '.' in s or 'e' in s.lower():
            return float(s)
        return int(s)
    except:
        pass
    # bare? error
    raise TomlError(lineno, raw, f"invalid value `{s}`")

def strip_comment(s):
    in_s=False
    s_char=None
    esc=False
    for i,ch in enumerate(s):
        if in_s:
            if esc:
                esc=False
            elif ch=='\\':
                esc=True
            elif ch==s_char:
                in_s=False
        else:
            if ch=='"' or ch=="'":
                in_s=True
                s_char=ch
            elif ch=='#':
                return s[:i]
    return s

def parse_basic_string(s, lineno, raw):
    # s starts with "
    # find closing unescaped "
    esc=False
    for i in range(1,len(s)):
        ch=s[i]
        if esc:
            esc=False
            continue
        if ch=='\\':
            esc=True
            continue
        if ch=='"':
            # end, rest should be empty/comment?
            rest=s[i+1:].strip()
            if rest and not rest.startswith('#'):
                raise TomlError(lineno, raw, "unexpected trailing")
            inner=s[1:i]
            # unescape: handle common
            inner=inner.replace('\\"','"').replace('\\\\','\\').replace('\\n','\n').replace('\\t','\t')
            return inner
    raise TomlError(lineno, raw, "unterminated string")

def parse_array(s, lineno, raw):
    # assume single line array? book.toml arrays are single line like ["a","b"] or []
    # Find matching ] respecting strings
    if not s.endswith(']'):
        raise TomlError(lineno, raw, "unterminated array")
    inner=s[1:-1].strip()
    if not inner:
        return []
    # split by commas not in strings/brackets?
    parts=split_toml_array(inner)
    res=[]
    for p in parts:
        p=p.strip()
        if not p or p.startswith('#'):
            continue
        # strip comment?
        p=strip_comment(p).strip()
        if not p:
            continue
        res.append(parse_toml_value(p, lineno, raw))
    return res

def split_toml_array(inner):
    parts=[]
    cur=""
    depth=0
    in_s=False
    s_char=None
    esc=False
    for ch in inner:
        if in_s:
            cur+=ch
            if esc:
                esc=False
            elif ch=='\\':
                esc=True
            elif ch==s_char:
                in_s=False
        else:
            if ch=='"' or ch=="'":
                in_s=True
                s_char=ch
                cur+=ch
            elif ch=='[':
                depth+=1
                cur+=ch
            elif ch==']':
                depth-=1
                cur+=ch
            elif ch==',' and depth==0:
                parts.append(cur)
                cur=""
            else:
                cur+=ch
    if cur.strip():
        parts.append(cur)
    return parts

def parse_inline_table(s, lineno, raw):
    if not s.endswith('}'):
        raise TomlError(lineno, raw, "unterminated inline table")
    inner=s[1:-1].strip()
    if not inner:
        return {}
    parts=split_toml_array(inner)
    d={}
    for p in parts:
        eq=find_eq(p)
        if eq is None:
            raise TomlError(lineno, raw, "invalid inline table")
        k=p[:eq].strip()
        v=p[eq+1:].strip()
        key=parse_toml_key(k, lineno, raw)
        d[key]=parse_toml_value(v, lineno, raw)
    return d

